    search: "%s LIKE ?%d ESCAPE '\\'",
    exists: "EXISTS (%s)",
    notExists: "NOT EXISTS (%s)",
    set: "%s = ?%d",
    setNull: "%s = NULL",
    pageKey: "page_key.%s",
    placeholder: "?%d",
    default: "",
    or: " OR ",
    group: "(%s)",
    where: " WHERE ",
    and: " AND ",
    orderBy: " ORDER BY ",
