/**
 * Opens the repositories of fixture-recurrence-db over db, a SqlDatabase, acting
 * as the user options names, or as the user it is when a string. The
 * behaviors' core is options.rules, or the rules package's, made when a
 * behavior first runs.
 */
export function createOrm(db: SqlDatabase, options?: string | null | OrmOptions): FixtureRecurrenceDbOrm {
  return sqliteOrm<FixtureRecurrenceDbRepositories>(db, fixtureRecurrenceDbOrm, withRulesCore(options, initSync)) as FixtureRecurrenceDbOrm;
}
